// Pass JSON fixtures generated by fixtures.py. OOS_SOLVER_DIST and OOR_READER_DIST select the built packages.
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { oor, solver } from "../../../wasm/test/helpers/runtime.mjs";

const measureVjp = process.argv.includes("--vjp");
for (const file of process.argv.slice(2).filter(arg => arg !== "--vjp")) {
  const deck = oor.createModel();
  deck.setSolution("LinearStatics");
  deck.caseControl.global.set("SinglePointConstrSelection", 1);
  deck.caseControl.global.set("DisplacementOutput", "All");
  deck.caseControl.addSubcase(1, { commands: [
    { name: "StaticLoadSelection", value: 2 }, { name: "SubcaseDesignConstrSelection", value: 7 },
    { name: "DesignObjectiveSelection", value: 11 },
  ] });
  const cards = JSON.parse(readFileSync(file));
  deck.addCards(cards.map(([type, ...fields]) => ({ type, fields })));
  if (measureVjp) {
    // Load all nodal displacements, then request only the derivative of volume.
    const nodes = cards.filter(row => row[0] === "Node").map(row => row[1]);
    deck.addCard({type: "DesignResp1", fields: [12, "ALLUX", "Displacement", null, null, 1, null, ...nodes]});
    deck.applyDefaults();
    const problem = solver.optimizationFromReader(oor, deck);
    const point = problem.evaluate();
    const weights = {responses: {11: [1]}};
    let product = point.vjp(weights);
    const start = performance.now();
    for (let i = 0; i < 200; ++i) product = point.vjp(weights);
    console.log(file, "vjp_ms=" + (performance.now()-start)/200);
    assert.ok(Math.abs(product.values[0] - 3.) < 1e-9 && Math.abs(product.values[1]) < 1e-9);
    point.delete(); problem.delete(); deck.delete();
    continue;
  }
  deck.applyDefaults();
  const start = performance.now();
  const problem = solver.prepareOptimization(oor, deck);
  const prepared = performance.now();
  const point = problem.evaluate();
  const evaluated = performance.now();
  const gradient = point.gradients();
  const differentiated = performance.now();
  const directions = new Float64Array([1,0,0,1]);
  let product = point.jvp(directions, {count: 2});
  const warm = performance.now();
  for (let i = 0; i < 20; ++i) product = point.jvp(directions, {count: 2});
  const end = performance.now();
  console.log(file, {prepare_ms: prepared-start, evaluate_ms: evaluated-prepared,
    gradient_ms: differentiated-evaluated, warm_jvp_ms: (end-warm)/20,
    gradient_factorisations: gradient.report.factorisations, warm_jvp_factorisations: product.report.factorisations,
    output_bytes: product.values.byteLength});
  const summary = point.optimizerValues();
  assert.equal(summary.partial, false);
  assert.equal(summary.uncertainMode, false);
  assert.ok(Math.abs(summary.objective-6) < 1e-9);
  const expected = [-.0075,-.000015,3,0];
  assert.equal(product.values.length, expected.length);
  expected.forEach((v,i) => assert.ok(Math.abs(product.values[i]-v) < 1e-9));
  const csr = point.constraintJacobian([[0,1],[0,1],[0]]);
  const second = problem.evaluate([3,1000]);
  assert.deepEqual(Array.from(csr.structure().rowOffsets), [0,2,4,5]);
  const reference = second.gradients().constraints;
  const values = csr.values(second);
  const flat = [...reference[0], ...reference[1], reference[2][0]];
  flat.forEach((v,i) => assert.ok(Math.abs(values[i]-v) < 1e-9));
  assert.deepEqual(Array.from(csr.constraints(second)), second.values().constraints.map(c => c.normalised));
  second.delete(); csr.delete(); point.delete(); problem.delete(); deck.delete();
}
